  -d '{
    "query": "mutation { issueUpdate(input: { id: \"i-m3\", labelIds: [\"aa055061-3a5f-559c-b34c-421850d4e3e8\"] }) { success issue { id identifier labels { nodes { id name } } } } }"
  }'

curl -s https://api.linear.app/graphql \
